  const item = $input.first().json ?? {};
  const rawCompany = String(item.company ?? item.org_name ?? '').trim();

  const add = (set, value) => {
    const clean = String(value ?? '').replace(/\s+/g, ' ').trim();
    if (clean) set.add(clean);
  };

  const variants = new Set();
  const normalizedSpaces = rawCompany
    .replace(/[._/\\]+/g, ' ')
    .replace(/[-\u2013\u2014]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  add(variants, rawCompany);
  add(variants, normalizedSpaces);

  // Try without common legal suffixes (BVBA/BV/NV/...) so we can match SF accounts like
  // "Resourcefull Houthalen" even if the inbound company includes "BVBA".
  if (normalizedSpaces) {
    const stripped = normalizedSpaces
      .replace(/\b(?:bvba|bv|nv|sa|srl|sprl|gmbh|ag|ltd|limited|inc|llc|plc|kg|oy|ab)\b\.?/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    add(variants, stripped);
  }

  if (normalizedSpaces) {
    const words = normalizedSpaces.split(' ').filter(Boolean);
    add(variants, words.join(' '));
    add(variants, words.join('-'));
    add(variants, words.join(''));
    add(variants, words.join('.'));
  }

  const asciiCompact = rawCompany
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9]/g, '');
  add(variants, asciiCompact);

  const companyVariants = [...variants].filter(Boolean).slice(0, 12);

